import hashlib

def crack_password(pass_phrase):
    # Create a hashing function
    aes_hash = hashlib.md5('sha256', pass_phrase)

    # Create a dictionary of likely passwords and their hashes
    def get_hashes(word_list, hash_func):
        return hash_func(**word_list)

    # Get candidate passwords
    all_candidates = []
    for word, hash_func in get_hashes(word_list, aes_hash):
        if word in pass_phrase:
            all_candidates.append(word)
        else:
            all_candidates.append(hash_func(**word))

    # Filter out known-good passwords
    pass_ok = all_candidates[pass_ok]

    # Check for collisions
    for p in all_candidates:
        for h in p:
            if p.lower() in pass_phrase:
                pass_ok.append(p)

    return pass_ok

